  ('home.reviews.1.name', 'Linda Van Staden', 'Review 1 name', 'text', 'Home – Reviews', 310),
  ('home.reviews.1.text', '2 Little Leashes has been a huge help with my dog, he absolutely loves his pack walks. Always comes back knackered but so happy! I always know where he is going and gets lots of photo updates. 10/10 would recommend 🙌', 'Review 1 text', 'textarea', 'Home – Reviews', 320),
  ('home.reviews.2.name', 'Donna Shaw', 'Review 2 name', 'text', 'Home – Reviews', 330),
  ('home.reviews.2.text', 'Meihana is the bomb, he''s so good with my girl MILO. She loves the runs he takes her on with the other fur babies. Interaction with the other dogs is soooo awesome. Meihana is a awesome trainer and she loves being with him and the other dogs would recommend him to anyone who is interested and looking for a great runner & dog handler.', 'Review 2 text', 'textarea', 'Home – Reviews', 340),
  ('home.reviews.3.name', 'Denise Frost', 'Review 3 name', 'text', 'Home – Reviews', 350),
