-- supabase/seed_site_content.sql
-- Seeds site_content with the current live values (generated from src/lib/content-defaults.ts).
-- Run manually in the Supabase SQL editor. Safe to re-run: existing values are
-- left alone; only label/type/section/sort_order are refreshed.

on conflict (key) do update set
  label      = excluded.label,
  type       = excluded.type,
  section    = excluded.section,
  sort_order = excluded.sort_order;
